<!doctype html><html><head><meta charset="utf-8"><title>{{ setting('site.name', 'GIG60') }} · Invoice {{ $order->uid }}</title><style>body{font:14px Arial;color:#111;max-width:800px;margin:40px auto;padding:0 24px}header{display:flex;justify-content:space-between;border-bottom:3px solid #111;padding-bottom:20px}h1{font-size:28px}.mut{color:#666}.box{border:1px solid #ddd;border-radius:12px;padding:16px;margin:18px 0}table{width:100%;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid #eee;text-align:left}.right{text-align:right}.total{font-size:18px;font-weight:bold}@media print{.print{display:none}}button{padding:10px 16px;border:0;border-radius:8px;background:#111;color:#fff}</style></head><body><header><div><h1>{{ setting('site.name', 'GIG60') }}</h1><div class="mut">GST invoice / payout statement</div></div><div class="right"><b>{{ $order->uid }}</b><br><span class="mut">{{ optional($order->created_at)->format('d M Y') }}</span></div></header><div class="box"><b>{{ $audience==='buyer' ? 'Bill to' : 'Statement for' }}</b><br>{{ $audience==='buyer' ? ($order->company->name ?? 'Business') : ($order->creator->name ?? 'Freelancer') }}<br><span class="mut">{{ $audience==='buyer' ? ($order->company->email ?? '') : ($order->creator->email ?? '') }}</span></div><table><thead><tr><th>Service</th><th>Description</th><th class="right">Amount</th></tr></thead><tbody><tr><td>{{ $order->service->title ?? 'GIG60 service' }}</td><td>{{ $order->turnaround }}</td><td class="right">&#8377;{{ number_format($audience==='buyer' ? ($order->subtotal + $order->fee) : $order->subtotal) }}</td></tr></tbody></table><div class="box"><div class="right">GST: &#8377;{{ number_format($order->tax_amount ?? 0) }}</div><div class="right total">{{ $audience==='buyer' ? 'Total paid' : 'Creator payout' }}: &#8377;{{ number_format($audience==='buyer' ? $order->total : $order->subtotal) }}</div></div><p class="mut">GST is shown separately. The creator statement shows the agreed creator payout; the buyer invoice shows the customer service amount and GST. This page can be printed or saved as PDF from your browser.</p><button class="print" onclick="window.print()">Print / Save as PDF</button></body></html>
